colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
g=[[0]*30 for _ in range(30)]
for tr in range(4):
 for tc in range(4):
  r=1+7*tr;c=1+7*tc
  for y in range(5):
   for x in range(5):
    g[r+y][c+x]=4 if y in (0,4) or x in (0,4) else colors[tr][tc]
# partial tile border visible in final row/column
for tc in range(4): g[29][1+7*tc]=4
for tr in range(4): g[1+7*tr][29]=4
# horizontal links for each tile-row and each inner row
for tr in range(4):
 for dy in (1,2,3):
  for color in set(colors[tr]):
   hits=[tc for tc in range(4) if colors[tr][tc]==color]
   if len(hits)>1:
    for tc in range(min(hits),max(hits)):
     for x in (6+7*tc,7+7*tc): g[1+7*tr+dy][x]=color
# vertical links
for tc in range(4):
 for dx in (1,2,3):
  seq=[colors[tr][tc] for tr in range(4)]
  for color in set(seq):
   hits=[tr for tr in range(4) if seq[tr]==color]
   if len(hits)>1:
    for tr in range(min(hits),max(hits)):
     for y in (6+7*tr,7+7*tr): g[y][1+7*tc+dx]=color
print('\n'.join(' '.join(map(str,row)) for row in g))

